Data:AddQuests(289, {
    { id = 5466, name = "The Lich, Ras Frostwhisper", side = "Both", requiredLevel = 57, xp = 23650, objective = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", description = "Use the Soulbound Keepsake on Ras Frostwhisper to make him human, then kill him and bring back his human head.", requires = { { id = 5465, name = "Soulbound Keepsake" } }, start = { description = "Caer Darrow, Western Plaguelands", location = { 1422, 70.4, 74 }, npc = "Magistrate Marduke" }, turnIn = { description = "Caer Darrow, Western Plaguelands", location = { 1422, 70.4, 74 }, npc = "Magistrate Marduke" }, items = {
